package env

import "strings"

func toMap(env []string) map[string]string {
	m := make(map[string]string, len(env))
	for _, v := range env {
		idx := strings.Index(v, "=")
		if idx < 0 {
			continue
		}
		m[v[:idx]] = v[idx+1:]
	}
	return m
}

